theorem MeasureTheory.Measure.extracted_1.{u_3, u_2} {α : Type u_2} {β : Type u_3} [inst : MeasurableSpace α]
  [inst_1 : MeasurableSpace β] {μ : Measure α} {ν : Measure β} [inst_2 : SigmaFinite ν] {A : Finset α} {B : Finset β}
  (hA : μ (↑A)ᶜ = 0) (hB : ν (↑B)ᶜ = 0) : (↑(A ×ˢ B))ᶜ = (↑A)ᶜ ×ˢ Set.univ ∪ Set.univ ×ˢ (↑B)ᶜ := sorry

theorem MeasureTheory.Measure.extracted_1.{u_4, u_2, u_1} {Ω : Type u_1} {α : Type u_2} {γ : Type u_4}
  [inst : MeasurableSpace Ω] [inst_1 : MeasurableSpace α] [inst_2 : MeasurableSpace γ] {X : Ω → α} {Z : Ω → γ}
  (hX : Measurable X) (hZ : Measurable Z) (μ : Measure Ω) (s : Set (γ × α)) (hs : MeasurableSet s) :
  (map (fun ω => (X ω, Z ω)) μ) (Prod.swap '' s) = μ ((fun a => (Z a, X a)) ⁻¹' s) := sorry

theorem MeasureTheory.Measure.extracted_1.{u_4, u_2, u_1} {Ω : Type u_1} {α : Type u_2} {γ : Type u_4}
  [inst : MeasurableSpace Ω] [inst_1 : MeasurableSpace α] [inst_2 : MeasurableSpace γ] {X : Ω → α} {Z : Ω → γ}
  (hX : Measurable X) (hZ : Measurable Z) (s : Set (γ × α)) (hs : MeasurableSet s) (s✝ : Set (γ × α)) :
  MeasurableSet s✝ → MeasurableSet (Prod.swap '' s✝) := sorry
